import{z as d,x as i,o,c as s,q as A,j as n,D as e,d as a,s as t,S as l,b as B}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"金本位的运作","description":"","frontmatter":{"title":"金本位的运作","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/mh-gold-standard-operation.md","filePath":"econ/mh-gold-standard-operation.md","lastUpdated":1791063341000}'),p={name:"econ/mh-gold-standard-operation.md"};function h(m,E,c,C,D,f){const r=i("Mermaid");return o(),s("div",null,[E[2]||(E[2]=A('<h1 id="金本位的运作" tabindex="-1">金本位的运作 <a class="header-anchor" href="#金本位的运作" aria-label="Permalink to &quot;金本位的运作&quot;">​</a></h1><div class="epigraph"><p>金本位的约束从不在黄金本身，而在各国政府愿意一次次把国内政策交给兑换承诺；规则是承诺的规则，黄金只是记账的秤。</p><footer>—— 据 Bordo and Kydland 1995；Bloomfield 1959 整理</footer></div><p><a href="/econ/mh-free-banking">上一课</a>把银行券的平价写成回兑套利与清算网络逐日挣出的结果，但「兑换到什么」仍缺一个跨国的共同锚。古典金本位（约 1870–1914）把这个锚配齐：各国货币都承诺兑金，彼此的比价就自动定了。主干已有<a href="/econ/gold-standard-depression">金本位与大萧条</a>讲它如何把一国通缩输出成全球萧条；本课只写它平时怎么运转，后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>几十种银行券与存款各自承诺兑金，两国货币之间的汇率凭什么稳定？国际收支失衡发生后，调整由谁执行、负担落在谁头上？还有可信性：承诺兑金的国家每天都有动机少兑一点——凭什么相信它不？</p><p>三个问题的答案共享同一个装置：铸币平价。每国把本币单位定义为固定重量的金，两国货币的比价就是两个含金量之比。缺口在于把「定义为多少」变成「永远兑到多少」的机制——这需要套利、需要规则、也需要政府克制。</p><h3 id="金点-物理写成的汇率走廊" tabindex="-1">金点：物理写成的汇率走廊 <a class="header-anchor" href="#金点-物理写成的汇率走廊" aria-label="Permalink to &quot;金点：物理写成的汇率走廊&quot;">​</a></h3><p>设美元–英镑平价为 \\(\\bar e\\)，运金到对方的成本率为 \\(c\\)，则汇率被钉在</p> \\[\\bar e(1-c) \\;\\le\\; e_t \\;\\le\\; \\bar e(1+c). \\]<p>带内汇率自由浮动，由外汇供需决定；一旦越界，运金比付汇便宜，套利者自己动手把汇率推回带内。带宽由运费、保险与利息决定，是物理参数写出的走廊。</p><p><span class="marginnote">直觉类比：金点走廊像一条两端装了弹簧的隧道——平时汇率在带内随意晃，由外汇供需推着走；一撞到端点，「运金」这根弹簧就把价格弹回来。带宽多宽不取决于政策意志，取决于运费、保险与资金占用利息这些物理与合同参数。</span></p><p><span class="marginnote">美元–英镑平价 \\(\\$4.8665\\)，黄金输出点约 \\(\\$4.89\\)、输入点约 \\(\\$4.85\\)，带宽不足半个百分点。带内看不出金本位的存在，越界的瞬间它以一箱金币的形态出现。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>调整机制来自休谟：赤字国金流出，货币与信贷收缩，物价与工资下行，出口重新变得便宜，失衡自动收窄；盈余国反向。这就是「游戏规则」：两国对称地让黄金流量驱动国内货币量。纪律与调整是同一枚硬币——正因为政府不消毒，承诺才可信。</p><p><span class="marginnote">数字实例：设想赤字使一国流通的金 base 缩了 10%，货币与信贷随之收缩，物价与工资大体同比例回落——出口报价等于打九折，竞争力立刻回来，失衡自动收窄。整条链条没有一行政策命令，全靠金属流动倒逼国内价格，这就是「纪律与调整是同一枚硬币」。</span></p><p>但实际执行不对称。Bloomfield 对 1880–1914 央行记录的重检发现，各国经常消毒金流动、保护国内信贷，赤字国被迫紧缩而盈余国可以袖手。于是承诺的重量几乎全压在赤字国与它们的债务人身上。制度史对此的回应是合作：1890 年巴林危机，英格兰银行联合法兰西银行与俄国国库的借款额度救市——锚能维持，部分靠这套临时性的同业救济。</p><p>承诺本身另有一层设计：Bordo 与 Kydland 指出，战时停兑并不毁掉信誉，因为规则里写着「战后按旧平价重返」；政府遵守的是规则而不是每一天的兑换。金本位于是像一条有豁免条款的合同——豁免被消费，条款却存续。</p>',17)),(o(),n(l,null,{default:e(()=>[t(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEF%5B%22%E8%B5%A4%E5%AD%97%E5%9B%BD%EF%BC%9A%E9%87%91%E6%B5%81%E5%87%BA%22%5D%20--%3E%20MON%5B%22%E8%B4%A7%E5%B8%81%E6%94%B6%E7%BC%A9%22%5D%0A%20%20MON%20--%3E%20PRC%5B%22%E7%89%A9%E4%BB%B7%E4%B8%8E%E5%B7%A5%E8%B5%84%E4%B8%8B%E8%A1%8C%22%5D%0A%20%20PRC%20--%3E%20FIX%5B%22%E5%87%BA%E5%8F%A3%E8%BD%AC%E5%BC%BA%EF%BC%8C%E5%A4%B1%E8%A1%A1%E6%94%B6%E7%AA%84%22%5D%0A%20%20SUR%5B%22%E7%9B%88%E4%BD%99%E5%9B%BD%EF%BC%9A%E9%87%91%E6%B5%81%E5%85%A5%22%5D%20--%3E%20ST%7B%22%E6%B6%88%E6%AF%92%E4%B8%8E%E5%90%A6%3F%22%7D%0A%20%20ST%20--%3E%7C%E4%B8%8D%E6%B6%88%E6%AF%92%7C%20EXP%5B%22%E8%B4%A7%E5%B8%81%E6%89%A9%E5%BC%A0%EF%BC%8C%E5%AF%B9%E7%A7%B0%E8%B0%83%E6%95%B4%22%5D%0A%20%20ST%20--%3E%7C%E6%B6%88%E6%AF%92%7C%20ASYM%5B%22%E8%B4%9F%E6%8B%85%E5%85%A8%E5%8E%8B%E8%B5%A4%E5%AD%97%E5%9B%BD%22%5D%0A%20%20ASYM%20--%3E%20COOP%5B%22%E5%90%8C%E4%B8%9A%E5%90%88%E4%BD%9C%E6%95%91%E6%B5%8E%E8%A1%A5%E4%BD%8D%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[a("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,[a("机制一是套利把汇率问题消解为运费问题：央行不需要买卖外汇维持平价，黄金点自己执行，这解释了为什么古典金本位下外汇干预罕见。机制二是承诺的可信性由对称调整买单：正因为紧缩真的会发生，兑换承诺才不是空头支票——这也把调整的政治成本写进了制度。不这么做会错在哪：只看「金本位稳定了汇率」，就看不见稳定由谁的失业与通缩支付；消毒与不对称执行正是它在 1930 年代崩溃时被反噬的内伤，那段见"),B("a",{href:"/econ/gold-standard-depression"},"金本位与大萧条"),a("。")],-1)),(o(),n(l,null,{default:e(()=>[t(r,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E6%B1%87%E7%8E%87%20e_t%20%E9%80%BC%E8%BF%91%E8%BE%93%E5%87%BA%E7%82%B9%22%5D%20--%3E%20Q%7B%22%E8%BF%90%E9%87%91%E4%B8%8E%E4%BB%98%E6%B1%87%E5%93%AA%E4%B8%AA%E4%BE%BF%E5%AE%9C%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E8%B6%8A%E7%95%8C%3A%20%E8%BF%90%E9%87%91%E6%9B%B4%E4%BE%BF%E5%AE%9C%22%7C%20SHIP%5B%22%E5%A5%97%E5%88%A9%E8%80%85%E6%94%B9%E8%BF%90%E9%BB%84%E9%87%91%E5%87%BA%E5%8F%A3%22%5D%0A%20%20Q%20--%3E%7C%22%E5%B8%A6%E5%86%85%3A%20%E4%BB%98%E6%B1%87%E6%9B%B4%E4%BE%BF%E5%AE%9C%22%7C%20FX%5B%22%E7%85%A7%E5%B8%B8%E4%B9%B0%E5%8D%96%E5%A4%96%E6%B1%87%22%5D%0A%20%20FX%20--%3E%20BAND%5B%22%E6%B1%87%E7%8E%87%E5%9C%A8%E5%B8%A6%E5%86%85%E8%87%AA%E7%94%B1%E6%B5%AE%E5%8A%A8%22%5D%0A%20%20SHIP%20--%3E%20PUSH%5B%22%E5%A4%96%E6%B1%87%E5%8D%96%E5%8E%8B%E6%B6%88%E5%A4%B1%2C%20e_t%20%E8%A2%AB%E6%8E%A8%E5%9B%9E%E5%B8%A6%E5%86%85%22%5D%0A%20%20PUSH%20--%3E%20AUTO%5B%22%E9%87%91%E7%82%B9%E8%87%AA%E5%B7%B1%E6%89%A7%E8%A1%8C%2C%20%E5%A4%AE%E8%A1%8C%E6%97%A0%E9%9C%80%E5%87%BA%E6%89%8B%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=A('<p><span class="marginnote">常见误区：初学者容易把金本位的汇率稳定当成免费午餐，实际上稳定的账单由赤字国的失业与通缩支付；盈余国再消毒金流动，这份账单还会加倍。所谓「承诺可信」的另一面，正是紧缩真的会发生——评价这个制度不能只看汇率稳不稳，还要看稳定由谁买单。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写战时停兑与战后复本位的财政逻辑，那是下一课；也不写崩溃与浮动，金本位与大萧条、<a href="/econ/bretton-woods-collapse">布雷顿森林与崩溃</a>已各司其职。金本位下没有相机选择的货币政策，物价长期由金矿供给决定——1890 年代南非与阿拉斯加的金脉如同一次外生宽松，这个「供给不归人管」的承袭来自第一课。它与现代的汇率制度谱系如何对位，见<a href="/econ/exchange-regimes">汇率制度</a>。</p><p>后课默认：「本位」意味着平价、金点与调整负担三者同时在场，缺一个就不叫本位。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>铸币平价加金点：汇率稳定由运费套利执行，不靠日常干预。</li><li>调整靠休谟机制，但实际执行不对称，负担压在赤字国与债务人。</li><li>可信性来自「战后按旧平价重返」的规则；停兑是条款内豁免，不是违约。</li><li>合作救济（如 1890 年巴林）是锚的非正式补丁。</li><li>出处：Hume 1752；Bloomfield 1959；Bordo and Kydland 1995；Eichengreen 1992。</li></ul>',6))])}const F=d(p,[["render",h]]);export{u as __pageData,F as default};
